package com.bank.lookup;

import java.util.logging.*;

public class SearchDemo {
    private static final Logger log = Logger.getLogger(SearchDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Sorted account keys for National Bank of India
        long[] accountKeys = {1001, 2001, 3001, 4001, 5001, 6001, 7001, 8001};

        BinarySearchService service = new BinarySearchService();

        log.info("Looking up Rajesh account key 5001 (expect found)");
        int idx1 = service.search(accountKeys, 5001);
        log.info("Result -> index=" + idx1);

        log.info("Looking up missing account key 9999 (expect not found)");
        int idx2 = service.search(accountKeys, 9999);
        log.info("Result -> index=" + idx2);
    }
}

