class BinarySearchService {
    private static final Logger log = Logger.getLogger(BinarySearchService.class.getName());

    // Classic binary search on a sorted array. O(log n) time, O(1) space.
    int search(long[] arr, long target) {
        int low = 0, high = arr.length - 1;

        while (low <= high) {
            int mid = low + (high - low) / 2;   // overflow-safe midpoint
            final int m = mid;
            log.fine(() -> "Checking index " + m + " value " + arr[m]);

            if (arr[mid] == target) {
                return mid;                     // found
            } else if (arr[mid] < target) {
                low = mid + 1;                  // target is in the right half
            } else {
                high = mid - 1;                 // target is in the left half
            }
        }
        return -1;                              // not present
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override
    public String format(java.util.logging.LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(record.getMillis()),
            record.getLevel().getName(),
            record.getMessage());
    }
}
